shots.draw_js:
clearScene();setBig(null);
setEq("$$\\text{target}=r+\\gamma\\max_{a'}\\hat Q(s',a';\\,w)$$","top");
note("标签里是同一个 w",640,310,"r lg");
setCap("你朝目标走一步，<b>目标自己也移了一步</b> —— 这不是回归该有的样子。");

clearScene();setEq(null);
setBig("目标动一点没关系","反正大家都在往好的方向走");
setCap("「都在变好」是<b>假设</b>，不是保证 —— L5 第七集说过没有下降保证。");

clearScene();setBig(null);
setEq("$$\\text{target}=r+\\gamma\\max_{a'}\\hat Q(s',a';\\,w^-)\\qquad w^-\\ \\text{frozen}$$","top");
note("另一份冻结的权重",640,300,"g lg");
note("每 C 步才同步一次",640,360,"y lg");
setCap("做法：<b>另存一份权重 w⁻</b>，只用来算目标，隔一段时间才同步。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:300,items:[
  {label:"C 步之内",sub:"标签固定 · 平稳回归",state:"on"},
  {label:"每 C 步",sub:"目标跳一次",state:"on"},
  {label:"代价",sub:"目标过时 C 步",state:"dead"}]});
note("把连续漂移换成离散跳变",640,420,"y");
setCap("它没有消掉非平稳，只是把<b>连续的漂移换成了偶尔的跳变</b>。");

clearScene();setBig(null);setEq(null);
note("仍然是半梯度",640,290,"r lg");
note("只是目标暂时不动",640,360,"y lg");
setCap("<b>指名反驳</b>：它<b>不</b>把半梯度变成真梯度，只是让标签在一段时间里固定。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:330,items:[
  {label:"函数逼近",sub:"卷积网络",state:"on"},
  {label:"自举",sub:"Q-learning 目标",state:"on"},
  {label:"离策略",sub:"max 与行为不一致",state:"on"}]});
note("DQN 三条全占",640,430,"r");
setCap("L5 说三条凑齐就可能发散。<b>DQN 一条不少。</b>");

clearScene();setEq(null);
setBig("两个补丁解决了不稳定","所以 DQN 是安全的");
setCap("它们解决了<b>两个病理</b>，而三要素<b>只被处理了两条半</b>。");

clearScene();setBig(null);setEq(null);
note("函数逼近 → 无补丁",340,250,"r lg","start");
note("自举 → 目标网络，减速",340,330,"y lg","start");
note("离策略 → 回放，加重",340,410,"r lg","start");
setCap("逐条对账：<b>一条没治，一条减速，一条反而更重</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:300,items:[
  {label:"症状",sub:"被压住了",state:"on"},
  {label:"病因",sub:"三条都还在",state:"dead"},
  {label:"保证",sub:"一条都没有",state:"dead"}]});
note("能跑通 ≠ 有保证",640,420,"r");
setCap("DQN <b>没有收敛保证</b>。它把发散的概率压到了工程上可接受。");

clearScene();setBig(null);setEq(null);
note("两个症状被压住",400,290,"g lg");
note("三个病因都还在",880,290,"r lg");
note("这是工程成果",640,400,"y lg");
setCap("<b>指名反驳</b>：补丁治的是<b>症状</b>，三要素这个<b>病因</b>一条都没被移除。");

clearScene();setBig(null);setEq(null);
note("Double DQN",400,270,"g lg");
note("优先回放",640,270,"b lg");
note("dueling",880,270,"v lg");
setCap("讲座末尾给了三个改动。<b>它们不是并列的三个 trick。</b>");

clearScene();setEq(null);
setBig("三个独立的工程改进","各自提点分数，背下来就行");
setCap("它们各自<b>对应前面一集的一个具体病理</b> —— 不需要单独记。");

clearScene();setBig(null);setEq(null);
note("Double DQN ← 最大化偏差",340,250,"g lg","start");
note("优先回放 ← 样本效率",340,330,"b lg","start");
note("dueling ← Q = V + A",340,410,"v lg","start");
setCap("三个改动，三个<b>已经讲过</b>的病。");

clearScene();setBig(null);
setEq("$$\\hat Q(s,a)=\\hat V(s)+\\hat A(s,a)$$","top");
note("多数状态下动作无关紧要",640,300,"y lg");
note("V 那一路可共享学习",640,360,"g lg");
setCap("dueling 的理由：<b>很多状态下选哪个动作都差不多</b>，但 V(s) 差别很大。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:300,items:[
  {label:"Double",sub:"修偏差（L4）",state:"on"},
  {label:"优先回放",sub:"修效率",state:"on"},
  {label:"dueling",sub:"修数据利用",state:"on"}]});
note("三条都没碰函数逼近",640,420,"r");
setCap("<b>指名反驳</b>：三个改动各有对应的病 —— <b>但没有一个碰三要素</b>。");
